import numpy as np
def equation(t, A, params):
    return params[0]*(A/(1+params[1]*A))*t**3 + params[2]*np.exp(-params[3]*A**2) + params[4]*np.sin(params[5]*np.sqrt(A))*t**1.5 + params[6]*np.exp(-params[7]*t)

import time
from scipy.optimize import least_squares
T0=time.time()
def known(q):
    c1,c3,c5=q[:3]
    return [A/(1+c1*A)*t**3, np.exp(-c3*A**2), np.sin(c5*np.sqrt(A))*t**1.5]
def gen(k,sn,a,b):
    if sn=='t': return t**a*A**b*np.exp(-k*t)
    if sn=='A': return t**a*A**b*np.exp(-k*A)
    if sn=='t2': return t**a*A**b*np.exp(-k*t**2)
    if sn=='sqrtA': return t**a*A**b*np.exp(-k*np.sqrt(A))
    if sn=='sin': return t**a*A**b*np.sin(k*t)
    if sn=='lin': return t**a*A**b/(1+k*t)
def rv(q,sn,a,b):
    X=np.column_stack(known(q)+[gen(q[3],sn,a,b)])
    bb=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
    return dA_dt-X@bb
res=[]
for sn in ['t','A','t2','sqrtA','sin','lin']:
